import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_kcnf(n, m):
        cnf = []
        for _ in range(m):
            clause = [random.randint(1, n), -random.randint(1, n)]
            cnf.append(clause)
        return cnf

    def tropical_root_system_length(cnf):
        monomials = set()
        for clause in cnf:
            for var in clause:
                if var > 0:
                    monomials.add(var)
                else:
                    monomials.add(-var)
        return len(monomials) ** (1/3)

    def resolution_proof_size(cnf):
        # Simplified heuristic for resolution proof size
        return math.ceil(len(cnf) ** 0.5)

    n = random.randint(5, 40)
    m = min(n * 2, 40)
    cnf = generate_kcnf(n, m)

    length = tropical_root_system_length(cnf)
    size = resolution_proof_size(cnf)

    return {
        "metric_name": "Tropical Root System Length vs Resolution Proof Size",
        "metric_value": length,
        "instances_tested": 1,
        "conjecture_holds": length >= m ** (1/3) and size <= math.sqrt(m),
        "counterexample": "" if conjecture_holds else f"CNF: {cnf}, Length: {length}, Size: {size}"
    }

if __name__ == "__main__":
